// Prefer exact id match first, then exact label match, then substring as last resort
function resolveNodeId(graph: GraphifyGraph, query: string): string | null {
  const q = query.toLowerCase();
  // 1. Exact id
  const exactId = graph.nodes.find((n) => n.id.toLowerCase() === q);
  if (exactId) return exactId.id;
  // 2. Exact label
  const exactLabel = graph.nodes.find((n) => n.label.toLowerCase() === q);
  if (exactLabel) return exactLabel.id;
  // 3. Substring fallback (log a warning for traceability)
  const substring = graph.nodes.find((n) => n.label.toLowerCase().includes(q) || n.id.toLowerCase().includes(q));
  if (substring) console.error(`[map-reader] fuzzy-resolved "${query}" → "${substring.id}" (substring match)`);
  return substring?.id ?? null;
}

